// Des: Tests for human input: curves, typing plan, live events
// Flo: pure geometry and plan asserts > live click, type, scroll against headless Chrome
// I/O: points and text > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const inpu = @import("ru-huma-inpu.zig"); const mock = @import("te-mock-page.zig"); const snap = @import("ru-page-snap.zig"); const fixt = @import("te-fixt-html.zig"); const T = std.testing;
fn profOf(tmpz: *std.testing.TmpDir, buff: []u8) ![]const u8 { return std.fmt.bufPrint(buff, ".zig-cache/tmp/{s}/prof", .{tmpz.sub_path}); }
test "curve ends exactly on the target and has the planned step count" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); var prn = std.Random.DefaultPrng.init(3); const from: inpu.Pt = .{ .x = 10, .y = 10 }; const to: inpu.Pt = .{ .x = 410, .y = 310 }; const path = try inpu.curve(aren.allocator(), from, to, prn.random()); try T.expectEqual(@as(usize, inpu.stepsFor(from, to)), path.len); try T.expectEqual(to.x, path[path.len - 1].x); try T.expectEqual(to.y, path[path.len - 1].y); }
test "curve eases in: first hop is shorter than a middle hop" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); var prn = std.Random.DefaultPrng.init(5); const from: inpu.Pt = .{ .x = 0, .y = 0 }; const path = try inpu.curve(aren.allocator(), from, .{ .x = 600, .y = 0 }, prn.random()); const first = @abs(path[0].x - from.x) + @abs(path[0].y - from.y); const mid = path.len / 2; const midd = @abs(path[mid].x - path[mid - 1].x) + @abs(path[mid].y - path[mid - 1].y); try T.expect(first < midd); }
test "curve is not a straight line and differs by seed" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); var one = std.Random.DefaultPrng.init(1); var two = std.Random.DefaultPrng.init(2); const to: inpu.Pt = .{ .x = 500, .y = 0 }; const pa = try inpu.curve(aren.allocator(), .{ .x = 0, .y = 0 }, to, one.random()); const pb = try inpu.curve(aren.allocator(), .{ .x = 0, .y = 0 }, to, two.random()); var off: f64 = 0; for (pa) |pnt| off = @max(off, @abs(pnt.y)); try T.expect(off > 1.0); try T.expect(pa[3].y != pb[3].y); }
test "short or zero move still has the minimum steps" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); var prn = std.Random.DefaultPrng.init(8); const path = try inpu.curve(aren.allocator(), .{ .x = 5, .y = 5 }, .{ .x = 5, .y = 5 }, prn.random()); try T.expectEqual(@as(usize, 3), path.len); try T.expectEqual(@as(f64, 5), path[2].x); try T.expectEqual(@as(usize, 28), inpu.stepsFor(.{ .x = 0, .y = 0 }, .{ .x = 5000, .y = 0 })); }
test "plan splits ascii keys, newline and non-ascii inserts" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const ops = try inpu.planType(aren.allocator(), "hi\nbạn"); try T.expectEqual(@as(usize, 6), ops.len); try T.expect(ops[0].kind == .key); try T.expect(ops[2].kind == .ent); try T.expect(ops[4].kind == .ins); try T.expectEqualStrings("ạ", ops[4].txt); try T.expect(ops[5].kind == .key); }
test "plan drops control chars and rejects bad utf8" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const ops = try inpu.planType(aren.allocator(), "a\x01\x07b"); try T.expectEqual(@as(usize, 2), ops.len); try T.expectError(error.InvalidUtf8, inpu.planType(aren.allocator(), "\xff\xfe")); const none = try inpu.planType(aren.allocator(), ""); try T.expectEqual(@as(usize, 0), none.len); }
test "live: human click, typing with Vietnamese, trusted events, delays in range" { const gpa = T.allocator; var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; var mok = try mock.start(gpa, T.io, try profOf(&tmpz, &buff), fixt.chat); defer mok.stop(); var aren = std.heap.ArenaAllocator.init(gpa); defer aren.deinit(); const alo = aren.allocator(); var prn = std.Random.DefaultPrng.init(11); const rnd = prn.random(); const nodes = try snap.axSnap(alo, mok.conn); const mom = snap.findNode(nodes, "listitem", "Mom").?; var pos = try inpu.clickAt(alo, mok.conn, rnd, .{ .x = 5, .y = 5 }, try snap.boxCenter(alo, mok.conn, mom.bid)); try T.expectEqualStrings("Mom", try snap.evalStr(alo, mok.conn, "ch")); try T.expectEqualStrings("true", try snap.evalStr(alo, mok.conn, "String(trust.length>0 && trust.every(function(x){return x}))")); try T.expect((try std.fmt.parseInt(i32, try snap.evalStr(alo, mok.conn, "moves"), 10)) >= 3); const box = snap.findNode(nodes, "textbox", "tin nhắn").?; pos = try inpu.clickAt(alo, mok.conn, rnd, pos, try snap.boxCenter(alo, mok.conn, box.bid)); const t0 = std.Io.Clock.awake.now(T.io).toMilliseconds(); try inpu.typeText(alo, mok.conn, rnd, "Chào Mom, 7h nhé", 90, 260); const el = std.Io.Clock.awake.now(T.io).toMilliseconds() - t0; try T.expect(el >= 16 * 90); try T.expectEqualStrings("Chào Mom, 7h nhé", try snap.evalStr(alo, mok.conn, "box.innerText")); try T.expect((try std.fmt.parseInt(i32, try snap.evalStr(alo, mok.conn, "keys"), 10)) >= 8); }
test "live: scroll dispatches wheel ticks" { const gpa = T.allocator; var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; var mok = try mock.start(gpa, T.io, try profOf(&tmpz, &buff), "<body style='height:5000px'><div id=a>x</div>"); defer mok.stop(); var aren = std.heap.ArenaAllocator.init(gpa); defer aren.deinit(); var prn = std.Random.DefaultPrng.init(2); try inpu.scrollBy(aren.allocator(), mok.conn, prn.random(), .{ .x = 100, .y = 100 }, 350); const sy = try std.fmt.parseInt(i32, try snap.evalStr(aren.allocator(), mok.conn, "Math.round(window.scrollY)"), 10); try T.expect(sy >= 300 and sy <= 400); }
